#!/usr/bin/env bash
# Builds the OS graph core (rust/os-graph, feature `wasm`) to WebAssembly and writes the
# generated files the web page embeds:
#
#   web/src/wasm/pkg/graph_kit_os.js     wasm-bindgen glue (--target web, no default module path)
#   web/src/wasm/pkg/graph_kit_os.d.ts   its declarations
#   web/src/wasm/bytes.ts                the .wasm bytes as base64, with the rustc version
#
# The page runs from file:// inside a WKWebView as one classic script, so it cannot fetch a
# .wasm file: the bytes are embedded and initialised with initSync({ module }). The .wasm
# itself is not kept in pkg/.
#
# Usage:
#   scripts/build-os-wasm.sh           regenerate the committed files
#   scripts/build-os-wasm.sh --check   build into a temp dir and diff against the committed files
#
# Wasm output is only reproducible with the same rustc, so --check is skipped (exit 0) when
# the local rustc differs from the one recorded in bytes.ts. CI has no Rust: it only reads
# the committed files.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
RUST_DIR="$ROOT/rust"
WASM_DIR="$ROOT/web/src/wasm"
PKG_DIR="$WASM_DIR/pkg"
BYTES_TS="$WASM_DIR/bytes.ts"
TARGET_DIR="${CARGO_TARGET_DIR:-$RUST_DIR/target}"
WASM_OUT="$TARGET_DIR/wasm32-unknown-unknown/release/graph_kit_os.wasm"
GENERATED_HEADER="// GENERATED by scripts/build-os-wasm.sh — do not edit"

mode="build"
case "${1:-}" in
  "") ;;
  --check) mode="check" ;;
  *) echo "usage: $0 [--check]" >&2; exit 2 ;;
esac

local_rustc() {
  rustup run stable rustc --version
}

# Build the crate and write the three generated files into the directory given as $1.
generate_into() {
  local out="$1"
  (cd "$RUST_DIR" && rustup run stable cargo build --release \
    --target wasm32-unknown-unknown --features wasm -p graph-kit-os)
  wasm-bindgen --target web --omit-default-module-path \
    --out-dir "$out" --out-name graph_kit_os "$WASM_OUT"
  local b64
  b64="$(base64 < "$out/graph_kit_os_bg.wasm" | tr -d '\n')"
  {
    printf '%s\n' "$GENERATED_HEADER"
    printf '// rustc: %s\n' "$(local_rustc)"
    printf 'export const OS_GRAPH_WASM_BASE64 = "%s";\n' "$b64"
  } > "$out/bytes.ts"
  rm -f "$out/graph_kit_os_bg.wasm"
}

if [ "$mode" = "build" ]; then
  tmp="$(mktemp -d "${TMPDIR:-/tmp}/os-wasm.XXXXXX")"
  trap 'rm -rf "$tmp"' EXIT
  generate_into "$tmp"
  mkdir -p "$PKG_DIR"
  cp "$tmp/graph_kit_os.js" "$tmp/graph_kit_os.d.ts" "$PKG_DIR/"
  cp "$tmp/bytes.ts" "$BYTES_TS"
  echo "wrote $PKG_DIR/graph_kit_os.js, graph_kit_os.d.ts and $BYTES_TS"
  exit 0
fi

# --check
if [ ! -f "$BYTES_TS" ]; then
  echo "check failed: $BYTES_TS is missing; run scripts/build-os-wasm.sh" >&2
  exit 1
fi
recorded="$(sed -n 's#^// rustc: ##p' "$BYTES_TS")"
current="$(local_rustc)"
if [ "$recorded" != "$current" ]; then
  echo "skipped: toolchain differs (recorded: $recorded; local: $current). The wasm output is only reproducible with the recorded rustc."
  exit 0
fi

tmp="$(mktemp -d "${TMPDIR:-/tmp}/os-wasm-check.XXXXXX")"
trap 'rm -rf "$tmp"' EXIT
generate_into "$tmp"
status=0
for pair in "graph_kit_os.js:$PKG_DIR/graph_kit_os.js" \
            "graph_kit_os.d.ts:$PKG_DIR/graph_kit_os.d.ts" \
            "bytes.ts:$BYTES_TS"; do
  built="$tmp/${pair%%:*}"
  committed="${pair#*:}"
  if ! diff -q "$built" "$committed" >/dev/null 2>&1; then
    echo "check failed: $committed differs from a fresh build" >&2
    status=1
  fi
done
if [ "$status" -ne 0 ]; then
  echo "run scripts/build-os-wasm.sh and commit the result" >&2
  exit 1
fi
echo "ok: generated OS wasm files match a fresh build"
